"""Isolated Step 3 evidence library for the clean path (PRD §6): an in-memory logical store and its dossier text, not the live writer.

A group is one stored statement. Its original record keeps its id and fields unchanged and gives the group its id. A later record that
Step 2 judged a repeat joins the group as a member and keeps its own id, text, fields and source article. Thesis links belong to the
group and remember the record that brought each one. A revision is its own group, linked to every group it revises; a repeat that also
revises another group adds that link to its own group, naming the member that established it.

The writer refuses rather than guesses: a failed comparison, several repeat targets, an unknown group, or a replayed record whose
placement differs from the first time raise `Refused` and write nothing. Physical storage and crash recovery are not provided here.

Later linking (Alex, 2026-11-08: a material statement no thesis takes is kept and linked when a related thesis opens; design
STEP1-CONDITIONS-DESIGN.md §§11.1, 17): when a thesis opens, every group whose original arrived with no link, from an earlier article,
is judged against it in batches. Each judged (thesis, group) pair is recorded once in `judged`; a batch that fails twice stays pending,
is reported, and is judged again on the next write to that thesis, against the same opening boundary (`opened_at`)."""
import copy

RECORD_FIELDS = ('id', 'article', 'publisher', 'publication_date', 'summary', 'passages', 'original_party', 'reporting_speaker', 'tier',
                 'statement_date', 'evidence_period', 'thesis_ids')


class Refused(Exception):
    """A Step 2 outcome the library will not write; nothing was changed."""


class Library:
    def __init__(self):
        self.groups = {}       # group id → {'original': record, 'members': [record], 'links': {thesis id: record id}, 'revises': [{'group', 'by'}]}
        self.placement = {}    # record id → group id
        self.order = []        # group ids in the order they were created
        self.judged = {}       # (thesis id, group id) → True | False, the later-linking ledger
        self.later_log = []    # one entry per later-linking call: thesis, article, linked, pending, judged
        self.opened_at = {}    # thesis id → the article that opened it: the boundary of its later linking
        self.pending = {}      # thesis id → group ids whose judgement failed twice and waits for the next write to the thesis

    def apply(self, record, outcome):
        """Write one record with its Step 2 outcome: {'kind': 'new' | 'repeat' | 'revision' | 'failed', 'repeat_of': [group ids],
        'revises': [group ids], 'reason': text}. Returns the id of the group that holds the record."""
        missing = [f for f in RECORD_FIELDS if f not in record]
        if missing:
            raise Refused(f'record lacks {missing}')
        kind, repeat_of, revises = outcome['kind'], list(outcome.get('repeat_of') or []), list(outcome.get('revises') or [])
        if kind == 'failed':
            raise Refused(f"comparison failed for {record['id']}: {outcome.get('reason', 'no reason given')}")
        if kind not in ('new', 'repeat', 'revision'):
            raise Refused(f'unknown outcome {kind!r}')
        if (kind == 'repeat') != bool(repeat_of) or len(repeat_of) > 1:
            raise Refused(f"a repeat names exactly one group; got {repeat_of} for outcome {kind}")
        if kind == 'revision' and not revises:
            raise Refused('a revision names the group it revises')
        for group_id in repeat_of + revises:
            if group_id not in self.groups:
                raise Refused(f'unknown group {group_id}')
        target = repeat_of[0] if repeat_of else record['id']
        if record['id'] in self.placement:
            if self.placement[record['id']] != target:
                raise Refused(f"{record['id']} was placed in {self.placement[record['id']]}, not {target}")
            group = self.groups[target]
            stored = next(r for r in [group['original']] + group['members'] if r['id'] == record['id'])
            if {k: v for k, v in stored.items() if k != 'thesis_ids'} != {k: v for k, v in record.items() if k != 'thesis_ids'}:
                raise Refused(f"{record['id']} names a stored record with different content; a changed record needs a new id")
            self._link(group, record)
            return target
        if kind == 'repeat':
            group = self.groups[target]
            group['members'].append(copy.deepcopy(record))
        else:
            group = {'original': copy.deepcopy(record), 'members': [], 'links': {}, 'revises': []}
            self.groups[target] = group
            self.order.append(target)
        self.placement[record['id']] = target
        self._link(group, record)
        for revised in revises:
            if revised != target and not any(r['group'] == revised for r in group['revises']):
                group['revises'].append({'group': revised, 'by': record['id']})
        return target

    def link_later(self, thesis_id, judge, before_article, batch=10):
        """Judge every group whose original arrived unlinked from an article before `before_article` against a newly opened thesis.
        judge(group ids) returns {group id: True | False} or raises. Returns {'linked': [...], 'pending': [...], 'judged': n}."""
        self.opened_at.setdefault(thesis_id, before_article)
        before_article = self.opened_at[thesis_id]
        todo = [g for g in self.order if not self.groups[g]['original']['thesis_ids']
                and self.groups[g]['original']['article'] < before_article and (thesis_id, g) not in self.judged]
        linked, pending = [], []
        for start in range(0, len(todo), batch):
            ids = todo[start:start + batch]
            answers = None
            for _attempt in range(2):
                try:
                    answers = judge(ids)
                    break
                except Exception:   # tried twice, then reported as pending, never saved as a judgement
                    answers = None
            if answers is None:
                pending += ids
                continue
            for group_id in ids:
                self.judged[(thesis_id, group_id)] = bool(answers[group_id])
                if answers[group_id]:
                    self.groups[group_id]['links'].setdefault(thesis_id, self.groups[group_id]['original']['id'])
                    linked.append(group_id)
        if pending:
            self.pending[thesis_id] = pending
        else:
            self.pending.pop(thesis_id, None)
        return {'linked': linked, 'pending': pending, 'judged': len(todo) - len(pending)}

    @staticmethod
    def _link(group, record):
        for thesis_id in record['thesis_ids']:
            group['links'].setdefault(thesis_id, record['id'])

    @staticmethod
    def articles(group):
        """Distinct source articles of a group, oldest first; two records from one article count once."""
        seen = []
        for record in [group['original']] + group['members']:
            if record['article'] not in seen:
                seen.append(record['article'])
        return seen

    def dossier(self, thesis_id):
        """Group ids linked to a thesis, in creation order."""
        return [g for g in self.order if thesis_id in self.groups[g]['links']]


def labelled_passages(record):
    """Each passage as a reader sees it: the source text Step 1 found, labelled 'Quote', or, when Step 1 did not find it (verified
    value None), the model's text labelled 'Unverified quote'. The model's own text stays in the record's `passages`. A record stored
    before verification was carried shows its passages as 'Quote'."""
    verified = record.get('verified_passages') or record['passages']
    return [('Quote', found) if found is not None else ('Unverified quote', passage) for passage, found in zip(record['passages'], verified)]


def record_text(record, label):
    attribution = record['original_party'] or 'unknown party'
    if record['reporting_speaker'] and record['reporting_speaker'] != record['original_party']:
        attribution += f", reported by {record['reporting_speaker']}"
    head = (f"[{label}] {record['publication_date']} · {record['publisher'] or 'unknown publisher'} · {attribution} · tier {record['tier']}"
            f" · stated {record['statement_date'] or 'unknown'} · period {record['evidence_period'] or 'unknown'}")
    quotes = '\n'.join(f'  {label_of}: "{p}"' for label_of, p in labelled_passages(record))
    return f"{head}\n  {record['summary']}\n{quotes}"


def group_text(library, group_id, label, labels, member_text=True, notes=()):
    """A group as a reader sees it: the original record, then each later report of the same statement in arrival order, with its own
    text when `member_text` is set and as a source line otherwise. Distinct articles are counted; repeats are not called confirmation."""
    group = library.groups[group_id]
    lines = [record_text(group['original'], label)]
    if group['members']:
        articles = library.articles(group)
        publishers = {r['publisher'] for r in [group['original']] + group['members']}
        lines.append(f'  Later reports of the same statement: {len(group["members"])} records from {len(articles) - 1} further articles '
                     f'({len(publishers)} publishers in all). Articles repeating a statement do not by themselves confirm it independently.')
        for member in group['members']:
            if member_text:
                party = '' if member['original_party'] == group['original']['original_party'] else f" · {member['original_party']}"
                quotes = ' '.join(f'"{p}"' if kind == 'Quote' else f'"{p}" (unverified)' for kind, p in labelled_passages(member))
                lines.append(f"    - {member['publication_date']} · {member['publisher']}{party}: {member['summary']}\n      Quote: {quotes}")
            else:
                lines.append(f"    - {member['publication_date']} · {member['publisher']}")
    for revised in group['revises']:
        lines.append(f"  Revises [{labels[revised['group']]}]." if revised['group'] in labels else '  Revises an entry outside this dossier.')
    lines += [f'  {note}' for note in notes]
    return '\n'.join(lines)

"""Seeded end-to-end diagnostic (D392): feed the clean library of one draw to the frozen production judge and write a views.sqlite the
frozen judgement scorer reads.

The replay mirrors production's dispatch order. Article k of the clean Step 1 run gets sequence number k; its records become evidence
`e<N>` in record order, with their sources and their Step 1 links at seq k. Repeat members are stored as their own evidence with a
same_claims relation to the group's original (D204), and a revision as a revisions row with the revised piece's links inherited
(writing.py:256-261), both at the seq of the article that brought them. Later links (library.later_log) are written at the seq of the
article whose processing made them. After a day's last article the frozen `judging.round_of_judgements` judges the seed views that got
a new link that day, with seq equal to that article's seq, as round.judge_day does. Nothing from a later article is in the database
when an earlier day is judged; `leakage_check` proves it from the database and from each sent request.

Only the 22 seeds are views. Links to theses the clean system opened are counted and dropped (they carry no ladder). A record with no
verified passage is dropped, as production drops a quote not in its item, and counted; the quote is the verified passages joined.

Usage: adapter.py <step1 trace.sqlite> <step2 folder> <output folder> [--live]"""
import argparse, collections, datetime, json, re, sqlite3, sys
from pathlib import Path

HERE = Path(__file__).resolve().parent
ROOT = HERE.parents[1]
sys.path[:0] = [str(ROOT / 'src')]
from hivemind import config, model, seeding  # noqa: E402
from hivemind.views import judging, store  # noqa: E402

SEEDS = ROOT / 'poc/seeds/nvda-2026-07-01-v2.json'
CONFIG = ROOT / 'poc/config/poc-v108.json'
SEED_IDS = {q['view_id'] for q in json.loads(SEEDS.read_text())['questions']}
SHOWN_EVIDENCE = re.compile(r'^- (e\d+) \[', re.M)
JUDGED_VIEW = re.compile(r'^Thesis (v\d+) \(', re.M)   # judging._lines_english's first line names the view judged


class Leak(Exception):
    pass


def load_draw(trace_path, step2_folder):
    """The clean draw in article order: the Step 1 items (sequence, input id, publication day) and the Step 3 library."""
    conn = sqlite3.connect(f'file:{trace_path}?mode=ro', uri=True)
    items = [{'sequence': s, 'input_id': i} for s, i in conn.execute("select sequence, input_id from trace order by sequence")]
    library = json.loads((Path(step2_folder) / 'library.json').read_text())
    return items, library


def records_by_article(library):
    """Every record the library holds (group originals and members), with its role: ('original', group id) or ('repeat', group id)."""
    by_article = collections.defaultdict(list)
    for group_id, group in library['groups'].items():
        by_article[group['original']['article']].append(('original', group_id, group['original']))
        for member in group['members']:
            by_article[member['article']].append(('repeat', group_id, member))
    for article in by_article:
        by_article[article].sort(key=lambda entry: library['order'].index(entry[2]['id']) if entry[2]['id'] in library['order'] else 10**9)
    return by_article


def quote_of(record):
    verified = [p for p in (record.get('verified_passages') or []) if p]
    return ' … '.join(verified)


class Adapter:
    def __init__(self, views_path, archive_path, transport=None, created_at='2026-07-01T00:00:00Z'):
        self.conn = store.open_db(views_path)
        self.archive = model.Archive(archive_path)
        self.cfg = config.load(CONFIG)
        self.transport = transport
        seeding.seed_views(self.conn, SEEDS, created_at)
        self.evidence_of = {}            # clean record id -> evidence id
        self.counts = collections.Counter()
        self.next_number = 1
        self.sent = []                   # (day, seq, view ids shown per request) for the leakage check

    def _new_evidence(self, record, seq):
        quote = quote_of(record)
        if not quote:
            self.counts['dropped: no verified passage'] += 1
            return None
        if len(quote) > 400:
            self.counts['quote longer than the judge shows (400)'] += 1
        evidence_id = f'e{self.next_number}'
        self.next_number += 1
        store.add_evidence(self.conn, evidence_id=evidence_id, quote=quote, one_line=record['summary'],
                           speaker=record.get('reporting_speaker') or record.get('original_party') or '',
                           original_who=record.get('original_party') or '', original_day=record.get('statement_date') or '',
                           tier=record['tier'], event_time=None, seq=seq, input_id=record['input_id'])
        store.add_source(self.conn, evidence_id, record['input_id'], 'news', record['publication_date'], None, seq)
        self.evidence_of[record['id']] = evidence_id
        self.counts['evidence written'] += 1
        return evidence_id

    def _link(self, evidence_id, thesis_id, seq, changed):
        if evidence_id is None:
            return
        if thesis_id not in SEED_IDS:
            self.counts['links to clean-opened theses dropped'] += 1
            return
        if store.link(self.conn, evidence_id, thesis_id, seq):
            changed.add(thesis_id)
            self.counts['links written'] += 1

    def article(self, k, entries, library, changed):
        for role, group_id, record in entries:
            evidence_id = self._new_evidence(record, k)
            for thesis_id in record.get('thesis_ids') or []:
                self._link(evidence_id, thesis_id, k, changed)
            if role == 'repeat' and evidence_id:
                original = self.evidence_of.get(library['groups'][group_id]['original']['id'])
                if original:
                    store.relate_same(self.conn, original, evidence_id, k)
                    self.counts['same_claims written'] += 1
        for group_id, group in library['groups'].items():
            for revision in group['revises']:
                by = library['groups'].get(revision['by'])
                if by is None or by['original']['article'] != k:
                    continue
                old, new = self.evidence_of.get(group['original']['id']), self.evidence_of.get(by['original']['id'])
                if old and new:
                    store.revise(self.conn, old, new, by['original'].get('statement_date') or '', k)
                    self.counts['revisions written'] += 1
                    for (view_id,) in self.conn.execute('select view_id from evidence_links where evidence_id=?', (old,)).fetchall():
                        self._link(new, view_id, k, changed)
        for entry in library['later_log']:
            if entry['article'] == k:
                for record_id in entry['linked']:
                    self._link(self.evidence_of.get(record_id), entry['thesis'], k, changed)

    def leakage_check(self, day, seq):
        for table, column in (('evidence', 'created_seq'), ('evidence_sources', 'seq'), ('evidence_links', 'seq'), ('same_claims', 'seq'),
                              ('revisions', 'seq')):
            top = self.conn.execute(f'select max({column}) from {table}').fetchone()[0]
            if top is not None and top > seq:
                raise Leak(f'{table}.{column} {top} is after day {day} (seq {seq})')
        late = self.conn.execute('select count(*) from evidence_sources where publication_day > ?', (day,)).fetchone()[0]
        if late:
            raise Leak(f'{late} sources published after {day}')

    def judge(self, day, seq, changed):
        """Judge the day's changed seed views with the frozen judge. The database holds nothing after the day (leakage_check), and every
        request must show exactly the evidence production's selection (`evidence_in_view`) chose for that view when its prompt was
        built: the selection is recorded in this thread, the comparison is made in the sending thread without touching the database."""
        self.leakage_check(day, seq)
        selected_by_view = {}
        production_selection = judging.evidence_in_view
        def recording_selection(conn, view_id):
            result = production_selection(conn, view_id)
            selected_by_view[view_id] = {piece['evidence_id'] for piece in result[0]}
            return result
        def watching(provider, request):
            text = request['messages'][-1]['content']
            shown = set(SHOWN_EVIDENCE.findall(text))
            named = JUDGED_VIEW.search(text)
            view_id = named.group(1) if named else None
            if view_id is None or view_id not in selected_by_view:
                raise Leak(f'a request on {day} names no judged view')
            if shown != selected_by_view[view_id]:
                raise Leak(f'{view_id} on {day}: the request shows {sorted(shown ^ selected_by_view[view_id])} unlike the selection')
            self.sent.append({'day': day, 'seq': seq, 'view': view_id, 'shown': sorted(shown)})
            return (self.transport or model.openai_transport)(provider, request)
        item = {'input_id': f'day:{day}', 'publication_day': day}
        judging.evidence_in_view = recording_selection
        try:
            judged = judging.round_of_judgements(self.archive, self.cfg, self.conn, sorted(changed), seq, item, transport=watching)
        finally:
            judging.evidence_in_view = production_selection
        self.conn.commit()
        self.counts['judgements'] += len(judged)
        return judged


def replay(trace_path, step2_folder, output_folder, transport=None):
    output = Path(output_folder)
    output.mkdir(parents=True, exist_ok=False)
    items, library = load_draw(trace_path, step2_folder)
    by_article = records_by_article(library)
    days = collections.OrderedDict()
    for entry in items:
        days.setdefault(_day_of(trace_path, entry['sequence']), []).append(entry['sequence'])
    if list(days) != sorted(days):
        raise SystemExit('the Step 1 articles are not in day order')
    adapter = Adapter(output / 'views.sqlite', output / 'archive.sqlite', transport=transport)
    for day, articles in days.items():
        changed = set()
        for k in articles:
            adapter.article(k, by_article.get(k, []), library, changed)
        adapter.conn.commit()
        if changed:
            adapter.judge(day, max(articles), changed)
    (output / 'adapter-counts.json').write_text(json.dumps(adapter.counts, indent=1))
    return adapter


def _day_of(trace_path, sequence):
    conn = sqlite3.connect(f'file:{trace_path}?mode=ro', uri=True)
    payload = json.loads(conn.execute('select request from trace where sequence=?', (sequence,)).fetchone()[0])['messages'][1]['content']
    return json.JSONDecoder().raw_decode(payload)[0]['source_item']['publication_date']


if __name__ == '__main__':
    parser = argparse.ArgumentParser()
    parser.add_argument('trace'); parser.add_argument('step2'); parser.add_argument('output'); parser.add_argument('--live', action='store_true')
    args = parser.parse_args()
    if not args.live:
        raise SystemExit('without --live this module is used by its tests only')
    result = replay(args.trace, args.step2, args.output)
    print(json.dumps(result.counts, indent=1))

